mapper.select:
select count(*)
from (
    select member_id, case_key
    from ai_case_handoff
    where create_time >= #{fromTime} and create_time < #{toTime}
    group by member_id, case_key
) as deduplicated_handoffs

select case
    when diagnosis_category in (
        'delivery_in_transit', 'delivery_exception', 'order_state_review',
        'facts_incomplete', 'policy_consultation', 'policy_insufficient',
        'tool_failure', 'needs_order_identifier'
    ) then diagnosis_category
    else 'other_pending_classification'
end as metric_key,
count(*) as total
from (
    select member_id, case_key, max(diagnosis_category) as diagnosis_category
    from ai_case_handoff
    where create_time >= #{fromTime} and create_time < #{toTime}
    group by member_id, case_key
) as deduplicated_handoffs
group by metric_key
